gnh(){return"Suspect"},
gni(){return"\xc9lev\xe9"},
gnj(){return"Moyen"},
gng(){return"Les lettres isol\xe9es, les num\xe9ros de page, les num\xe9ros de section et les fragments OCR/PDF trop courts ont \xe9t\xe9 exclus."},
nd(a){return""+a+" \xe9l\xe9ments"},
gne(){return"Aucun contenu suspect"},
gno(){return"\xc9lev\xe9"},
gnp(){return"Moyen"},
gnm(){return"Plusieurs signaux de mod\xe8le penchent fortement vers l'IA"},
gnn(){return"Le signal du mod\xe8le au niveau de la phrase est \xe9lev\xe9"},
nk(a){return"Emplacement d'origine "+a},
nl(a,b){return"Emplacement d'origine "+a+" \xb7 "+b},
nq(a){return"Phrase n\xb0 "+a},
gnf(){return"Preuve :"},
gkW(){return"Authenticit\xe9 des hyperliens"},
gtN(){return"Aucun hyperlien d\xe9tect\xe9 dans ce document."},
gtH(){return"V\xe9rification des liens\u2026"},
