gv2(){return"\uba3c\uc800 \ub85c\uceec OCR \uc11c\ubc84 URL\uc744 \uc785\ub825\ud558\uc138\uc694."},
gv3(){return"\ub85c\uceec OCR \uc11c\ubc84\uac00 \uc2e4\ud589 \uc911\uc774\uba70 \uc900\ube44\ub418\uc5c8\uc2b5\ub2c8\ub2e4."},
